function calculatePowerFactor(regVal) {
    let PF_Val;
    let PF_Type;

    if (regVal > 1) {
        PF_Val = 2 - regVal;
        PF_Type = 'leading';
    } else if (regVal < -1) {
        PF_Val = -2 - regVal;
        PF_Type = 'leading';
    } else if (Math.abs(regVal) === 1) {
        PF_Val = regVal;
        PF_Type = 'at unity';
    } else {
        PF_Val = regVal;
        PF_Type = 'lagging';
    }

    return PF_Val;
}

